// Blox Legends service worker (generated by tools/build.mjs — do not edit _site/sw.js).
// Each release is one versioned cache containing EVERY file. Install is
// all-or-nothing, so a launch can never mix old and new files.
const VERSION = '__VERSION__';
const FILES = __FILES__;
const CACHE = `blox-legends-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith('blox-legends') && key !== CACHE) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      let hit = await cache.match(req, { ignoreSearch: true });
      if (!hit && req.mode === 'navigate') hit = (await cache.match('./')) || (await cache.match('index.html'));
      if (hit) return hit;
      return fetch(req);
    })(),
  );
});
